const listConversations = `-- name: ListConversations :many
SELECT c.id, c.uuid, c.organization_id, c.brand_id, c.channel, c.contact_e164, c.contact_name, c.user_id, c.last_message_at, c.created_at, c.updated_at, c.status, c.ai_mode, c.ai_paused_until, c.assigned_user_id, c.assigned_org_id, c.identity_kind, c.identity_user_id, c.identity_org_id, c.identity_resolved_at, c.locale, c.last_inbound_at, c.unread_count, c.ai_consent_at, c.visitor_lead_id FROM conversations c
WHERE ($1::text IS NULL OR c.channel = $1::text)
  AND (COALESCE(cardinality($2::text[]), 0) = 0 OR c.status = ANY ($2::text[]))
  AND (COALESCE(cardinality($3::text[]), 0) = 0 OR c.identity_kind = ANY ($3::text[]))
  AND (COALESCE(cardinality($4::text[]), 0) = 0 OR c.ai_mode = ANY ($4::text[]))
  AND (COALESCE(cardinality($5::bigint[]), 0) = 0 OR c.assigned_user_id = ANY ($5::bigint[]))
  AND ($6::timestamptz IS NULL OR c.last_message_at >= $6::timestamptz)
  AND ($7::timestamptz IS NULL OR c.last_message_at < $7::timestamptz)
  AND ($8::bool IS NULL OR (c.unread_count > 0) = $8::bool)
  AND ($9::text IS NULL
       OR c.contact_name ILIKE '%' || $9::text || '%'
       OR (regexp_replace($9::text, '[^0-9]', '', 'g') <> ''
           AND c.contact_e164 LIKE '%' || regexp_replace($9::text, '[^0-9]', '', 'g') || '%')
       OR EXISTS (
           SELECT 1 FROM users u
           WHERE u.id = c.identity_user_id
             AND (u.name || ' ' || COALESCE(u.surname, '')) ILIKE '%' || $9::text || '%'))
ORDER BY
  CASE WHEN NOT $10::bool AND $11::text = 'created_at' THEN c.created_at END ASC,
  CASE WHEN $10::bool AND $11::text = 'created_at' THEN c.created_at END DESC,
  CASE WHEN NOT $10::bool AND $11::text = 'last_message_at' THEN c.last_message_at END ASC NULLS LAST,
  CASE WHEN $10::bool AND $11::text = 'last_message_at' THEN c.last_message_at END DESC NULLS LAST,
  CASE WHEN NOT $10::bool AND $11::text = 'unread_count' THEN c.unread_count END ASC,
  CASE WHEN $10::bool AND $11::text = 'unread_count' THEN c.unread_count END DESC,
  CASE WHEN $10::bool THEN c.id END DESC,
  c.id ASC
LIMIT $13 OFFSET $12
`

